/// RCV-04: wrong full identities are corruption even when accelerators collide.
#[test]
fn stored_identity_must_match_the_requested_key() {
    let store = MemoryStore::default();
    let a = txid_with_prefix(0xDEAD_BEEF, 1);
    let b = txid_with_prefix(0xDEAD_BEEF, 2);
    let hash = Hash256::from_le_bytes(&[7; 32]);
    let mut seed = PersistentUtxoSet::new(store.clone());
    seed.connect_block(&block(two_output_add(a, &[0x51], &[0x52]), vec![]), &hash, CoinDurability::Durable)
        .expect("seed canonical row");
    let bytes = store.get(ColumnFamily::CoinRecords, a.as_byte_array()).expect("read row").expect("row");
    let mut batch = store.new_batch();
    batch.put(ColumnFamily::CoinRecords, b.as_byte_array(), &bytes);
    store.write(batch).expect("seed wrong key");
    let mut coins = PersistentUtxoSet::new(store);
    assert!(matches!(coins.get(&outpoint(b, 0)), Err(PersistentUtxoError::CorruptStoredRecord(id)) if id == b.into()));
    assert_eq!(coins.ledger().expect("ledger").resident.records, 0);
    assert!(coins.get(&outpoint(a, 0)).expect("correct key").is_some());
}

/// RCV-04: neither point-read nor iterator errors become ordinary absence.
#[test]
fn read_and_ledger_failures_remain_errors() {
    let store = MemoryStore::default();
    let mut coins = PersistentUtxoSet::new(store.clone());
    store.fail_reads.store(true, std::sync::atomic::Ordering::Relaxed);
    assert!(matches!(coins.get(&outpoint(txid(20), 0)), Err(PersistentUtxoError::Storage(_))));
    assert!(matches!(coins.ledger(), Err(PersistentUtxoError::Storage(_))));
}

/// RCV-04: malformed spend-only rows must fail before a no-op batch can succeed.
#[test]
fn malformed_spend_only_row_cannot_be_ignored() {
    let store = MemoryStore::default();
    let a = txid(21);
    let mut batch = store.new_batch();
    batch.put(ColumnFamily::CoinRecords, a.as_byte_array(), b"corrupt");
    store.write(batch).expect("seed corruption");
    let mut coins = PersistentUtxoSet::new(store.clone());
    for mode in [CoinDurability::Deferred, CoinDurability::Durable, CoinDurability::CasGuarded] {
        let result = coins.connect_block(&block(vec![], vec![outpoint(a, 0)]), &a, mode);
        assert!(matches!(result, Err(PersistentUtxoError::CorruptStoredRecord(id)) if id == a.into()));
    }
    assert_eq!(store.get(ColumnFamily::CoinRecords, a.as_byte_array()).expect("unchanged row"), Some(b"corrupt".to_vec()));
}

/// RCV-04: a failed write fences even the already-mutated in-memory view.
#[test]
fn write_failure_requires_recovery_before_serving_or_retrying() {
    let store = MemoryStore::default();
    let mut coins = PersistentUtxoSet::new(store.clone());
    let a = txid(22);
    store.fail_writes.store(true, std::sync::atomic::Ordering::Relaxed);
    assert!(matches!(coins.connect_block(&block(two_output_add(a, &[0x51], &[0x52]), vec![]), &a, CoinDurability::Durable), Err(PersistentUtxoError::Storage(_))));
    assert!(matches!(coins.get(&outpoint(a, 0)), Err(PersistentUtxoError::RecoveryRequired)));
    assert!(matches!(coins.connect_block(&block(vec![], vec![]), &a, CoinDurability::Durable), Err(PersistentUtxoError::RecoveryRequired)));
    assert!(matches!(coins.undo_block(&Default::default(), CoinDurability::Durable), Err(PersistentUtxoError::RecoveryRequired)));
    assert!(matches!(coins.flush(), Err(PersistentUtxoError::RecoveryRequired)));
    assert!(matches!(coins.ledger(), Err(PersistentUtxoError::RecoveryRequired)));
    assert!(store.get(ColumnFamily::CoinRecords, a.as_byte_array()).expect("store unchanged").is_none());
}

/// RCV-04: a real foreign update fails CAS; no stale successful view is exposed.
#[test]
fn guarded_mismatch_fences_cache_until_explicit_reopen() {
    let store = MemoryStore::default();
    let a = txid(23);
    let mut coins = PersistentUtxoSet::new(store.clone());
    coins.connect_block(&block(two_output_add(a, &[0x51], &[0x52]), vec![]), &a, CoinDurability::Durable).expect("seed");
    let mut other = PersistentUtxoSet::new(store.clone());
    other.connect_block(&block(vec![], vec![outpoint(a, 0)]), &a, CoinDurability::Durable).expect("foreign update");
    assert!(matches!(coins.connect_block(&block(vec![], vec![outpoint(a, 1)]), &a, CoinDurability::CasGuarded), Err(PersistentUtxoError::ConditionMismatch)));
    assert!(matches!(coins.get(&outpoint(a, 1)), Err(PersistentUtxoError::RecoveryRequired)));
    let mut reopened = PersistentUtxoSet::new(store);
    assert!(reopened.get(&outpoint(a, 0)).expect("foreign spend").is_none());
    assert!(reopened.get(&outpoint(a, 1)).expect("unmodified sibling").is_some());
}

/// FP-05 / CL-14: read refills enforce the same budget as write refills.
#[test]
fn read_refills_are_evicted_after_copying_the_output() {
    let store = MemoryStore::default();
    let a = txid(24);
    let mut coins = PersistentUtxoSet::new(store);
    coins.connect_block(&block(two_output_add(a, &[0x51], &[0x52]), vec![]), &a, CoinDurability::Durable).expect("seed");
    coins.set_resident_budget(1);
    for _ in 0..3 {
        assert_eq!(coins.get(&outpoint(a, 1)).expect("read").expect("output").value, 200);
        assert_eq!(coins.ledger().expect("ledger").resident.accounted_bytes(), 0);
    }
}

/// A missing vout in a resident record does not re-read or duplicate that record.
#[test]
fn resident_missing_output_does_not_reload_the_transaction() {
    let store = MemoryStore::default();
    let a = txid(25);
    let mut coins = PersistentUtxoSet::new(store.clone());
    coins.connect_block(&block(two_output_add(a, &[0x51], &[0x52]), vec![]), &a, CoinDurability::Durable).expect("seed");
    store.fail_reads.store(true, std::sync::atomic::Ordering::Relaxed);
    assert!(coins.get(&outpoint(a, 99)).expect("resident miss").is_none());
}

/// FP-05 / CL-14: eviction retains pinned candidates until flush releases them.
#[test]
fn flush_evicts_previously_pinned_records() {
    let a = txid(26);
    let mut coins = PersistentUtxoSet::new(MemoryStore::default());
    coins.connect_block(&block(two_output_add(a, &[0x51], &[0x52]), vec![]), &a, CoinDurability::Durable).expect("seed");
    coins.connect_block(&block(vec![], vec![outpoint(a, 0)]), &a, CoinDurability::Deferred).expect("deferred spend");
    coins.set_resident_budget(1);
    assert_eq!(coins.ledger().expect("pinned").resident.records, 1);
    coins.flush().expect("flush");
    let ledger = coins.ledger().expect("ledger");
    assert_eq!(ledger.resident.accounted_bytes(), 0);
    assert_eq!(ledger.retained_before_image_bytes, 0);
    assert!(coins.get(&outpoint(a, 1)).expect("reload").is_some());
}
